mapper.insert:
insert into bss_transfer ( id, transfer_no, status, transfer_fm_wh_cd, transfer_to_wh_cd, transfer_to_loc_cd, transfer_registered_by, transfer_registered_at, completed_by, completed_at, canceled_by, canceled_at, memo, completion_memo, delete_flg,
) values ( #{id}, #{transferNo}, #{status}, #{transferFmWhCd}, #{transferToWhCd}, #{transferToLocCd}, #{transferRegisteredBy}, #{transferRegisteredAt}, #{completedBy,jdbcType=VARCHAR}, #{completedAt,jdbcType=VARCHAR}, #{canceledBy,jdbcType=VARCHAR}, #{canceledAt,jdbcType=VARCHAR}, #{memo,jdbcType=VARCHAR}, #{completionMemo,jdbcType=VARCHAR}, #{deleteFlg},
)

insert into bss_transfer_detail ( id, transfer_no, detail_no, transfer_request_no, transfer_request_detail_no, inventory_detail_id, item_code, item_name, classification, storage_qty, move_qty, lost_damaged_qty, disposal_qty, source_pallet_no, dest_pallet_no, pallet_issue_flg, status, remarks, delete_flg,
) values
( #{item.id}, #{item.transferNo}, #{item.detailNo}, #{item.transferRequestNo,jdbcType=VARCHAR}, #{item.transferRequestDetailNo,jdbcType=INTEGER}, #{item.inventoryDetailId}, #{item.itemCode}, #{item.itemName,jdbcType=VARCHAR}, #{item.classification}, #{item.storageQty}, #{item.moveQty}, #{item.lostDamagedQty,jdbcType=NUMERIC}, #{item.disposalQty,jdbcType=NUMERIC}, #{item.sourcePalletNo}, #{item.destPalletNo}, #{item.palletIssueFlg}, #{item.status}, #{item.remarks,jdbcType=VARCHAR}, #{item.deleteFlg}, #{item.createTime}, #{item.createBy}, #{item.createPgId}, #{item.updateTime}, #{item.updateBy}, #{item.updatePgId}, #{item.version} )

mapper.select:
select o.id as id, o.transfer_no as transferNo, o.status as status, coalesce(nullif(trim(st.dict_label), ''), o.status) as statusLabel, o.transfer_fm_wh_cd as sourceWhCd, coalesce(nullif(fw.wh_nm, ''), o.transfer_fm_wh_cd) as sourceWarehouse, o.transfer_to_wh_cd as destWhCd, coalesce(nullif(tw.wh_nm, ''), o.transfer_to_wh_cd) as destWarehouse, o.transfer_to_loc_cd as destLocCd, coalesce(nullif(trim(ru.nick_name), ''), o.transfer_registered_by) as registrar, nullif(o.transfer_registered_at, '') as registeredDate, coalesce(nullif(trim(cu.nick_name), ''), o.completed_by) as completer, nullif(o.completed_at, '') as completedDate, nullif(o.memo, '') as memo from bss_transfer o left join mast_warehouse fw on fw.wh_cd = o.transfer_fm_wh_cd left join mast_warehouse tw on tw.wh_cd = o.transfer_to_wh_cd left join sys_dict_data st on st.dict_type = 'bss_transfer_status' and st.dict_value = o.status left join sys_user ru on ru.user_name = o.transfer_registered_by left join sys_user cu on cu.user_name = o.completed_by where o.delete_flg = '0'
and not exists ( select 1 from bss_transfer_detail rd where rd.transfer_no = o.transfer_no and rd.delete_flg = '0' and rd.transfer_request_no is not null )
and o.transfer_no like concat('%', #{moveNo}, '%')
and o.transfer_fm_wh_cd = #{sourceWhCd}
and o.transfer_to_wh_cd = #{destWhCd}
and o.transfer_to_loc_cd = #{destLocCd}
and exists ( select 1 from bss_transfer_detail d where d.transfer_no = o.transfer_no and d.delete_flg = '0' and d.item_code like concat('%', #{itemCode}, '%') )
and exists ( select 1 from bss_transfer_detail d where d.transfer_no = o.transfer_no and d.delete_flg = '0' and d.item_name like concat('%', #{itemName}, '%') )
and ( o.transfer_registered_by like concat('%', #{registrar}, '%') or ru.nick_name like concat('%', #{registrar}, '%') )
and ( o.completed_by like concat('%', #{completer}, '%') or cu.nick_name like concat('%', #{completer}, '%') )
and >= #{registeredFrom}
and <= concat(#{registeredTo}, '999999')
and >= #{completedFrom}
and <= concat(#{completedTo}, '999999')
and o.status in
#{status}
order by o.update_time desc nulls last, o.transfer_no

select d.transfer_no as transferNo, d.item_code as itemCode, d.item_name as itemName from bss_transfer_detail d where d.delete_flg = '0' and d.transfer_no in
#{transferNo}
order by d.transfer_no, d.detail_no

select h.loc_cd
from bss_inventory_history h
where h.transfer_no = #{transferNo}
  and h.item_code = #{itemCode}
  and h.pallet_no = #{palletNo}
order by h.create_time desc
limit 1

select cast(d.id as varchar) as id, d.item_code as itemCode, d.item_name as itemName, coalesce(nullif(cl.dict_label, ''), d.classification) as classification, d.wh_cd as whCd, coalesce(nullif(mw.wh_nm, ''), d.wh_cd) as whName, d.loc_cd as locCd, d.pallet_no as palletNo, d.qty as qty, d.allocation_qty as allocationQty from bss_inventory_detail d left join mast_warehouse mw on mw.wh_cd = d.wh_cd left join sys_dict_data cl on cl.dict_type = 'bss_classification' and cl.dict_value = d.classification where d.delete_flg = '0' and d.status = #{status}
and d.wh_cd = #{whCd}
and d.item_code like concat('%', #{itemCode}, '%')
and d.item_name like concat('%', #{itemName}, '%')
order by d.item_code, d.pallet_no
